style.css:
@-moz-document domain("pinterest.com"), domain("co.pinterest.com") {
body,
  html,
  [data-test-id="main-layout"],
  #__PWS_ROOT__ {
    background-color: #0b0b0f !important;
    background-image: url("https://i.imgur.com/zXwlNOb.jpeg"); 
    background-size: cover !important;
    background-attachment: fixed !important;
    background-position: center !important;
  }

  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.65);
    z-index: -1;
  }

  div[data-test-id="pin"] {
    background: rgba(20, 20, 25, 0.75) !important;
    border-radius: 16px !important;
    box-shadow: 0 0 25px rgba(0,0,0,0.6) !important;
  }

  * {
    color: #e6e6eb !important;
  }

  header,
  nav {
    background: rgba(10, 10, 15, 0.85) !important;
    backdrop-filter: blur(12px) !important;
  }

  input,
  textarea {
    background-color: #111118 !important;
    color: #ffffff !important;
    border-radius: 12px !important;
  }

  [style*="background-color: rgb(255, 255, 255)"] {
    background-color: transparent !important;
  }
}
